class Solution:
    def findCoins(self, numWays: List[int]) -> List[int]:
        n = len(numWays)
        cur = [0] * (n + 1)
        cur[0] = 1
        res = []
        for i in range(1, n + 1):
            if cur[i] == numWays[i - 1]:
                continue
            if cur[i] + 1 == numWays[i - 1]:
                res.append(i)
                for j in range(i, n + 1):
                    cur[j] += cur[j - i]
            else:
                return []
        return res

