class Solution {
public:
    vector<int> findCoins(vector<int>& numWays) {
        int n = numWays.size();
        vector<long long> cur(n + 1, 0);
        cur[0] = 1;
        vector<int> res;
        for (int i = 1; i <= n; i++) {
            if (cur[i] == numWays[i - 1]) continue;
            if (cur[i] + 1 == numWays[i - 1]) {
                res.push_back(i);
                for (int j = i; j <= n; j++) cur[j] += cur[j - i];
            } else return {};
        }
        return res;
    }
};

