class Solution {
    public int[] findCoins(int[] numWays) {
        int n = numWays.length;
        long[] cur = new long[n + 1];
        cur[0] = 1;
        List<Integer> tmp = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (cur[i] == numWays[i - 1]) continue;
            if (cur[i] + 1 == numWays[i - 1]) {
                tmp.add(i);
                for (int j = i; j <= n; j++) cur[j] += cur[j - i];
            } else return new int[0];
        }
        int[] res = new int[tmp.size()];
        for (int i = 0; i < res.length; i++) res[i] = tmp.get(i);
        return res;
    }
}

